window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0cfd9a04da3b8e74"]={"versions": [{"id": "FIG-0cfd9a04da3b8e74", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Metamodell-Strategiediagramm (informelle „Cloud“-Darstellung auf Methodik-Ebene, kein formales UML-Klassen- oder Verhaltensdiagramm).</li>\n<li><strong>Technischer Zweck & Kontext:</strong> Einordnung innerhalb der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_TPS_MachineConfiguration</code>, Kapitel 2 <em>Modeling Strategies for deriving M1 Model Content</em>). Das Diagramm visualisiert die vierte Modellierungsstrategie (Abschnitt 2.4.1), bei der die Parametrierung eines Functional Clusters (FC) bzw. der Machine vollständig und ausschließlich aus dem M1-Entwurfsmodell (<em>Design Model</em>) bezogen wird, ohne dass ein separates Konfigurations- oder Deployment-Modell (<em>Configuration Model</em>) existiert oder instanziiert werden muss.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><code>Design</code>: Symbolisiert die Gesamtheit der M1-Design-Artefakte (z. B. SWC-Typdefinitionen, Service Interfaces, System-Architektur-Modelle).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Singuläre Entität ohne Relationen oder Kanten.</li>\n<li>Es existiert keine Ziel-Konfigurationsentität und somit kein M2-Mapping, keine Transformationsbeziehung und keine Referenzierungssemantik (wie <code>instanceRef</code> oder flache Referenzen).</li>\n<li>Formal-syntaktische Metamodell-Stereotypen («atpSplitable», «isOfType») sind im Schaubild nicht instanziiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeitverhalten:</strong> Nicht zutreffend; rein statisches, konzeptionelles Modellierungs-Paradigma.</li>\n<li><strong>Tooling- & Generierungs-Pipeline:</strong></li>\n<li>Zur Generierungszeit entfällt der Schritt der M1-Modelltransformation oder der Synthese eines separaten Manifest-Zwischenmodells.</li>\n<li>Generatoren des betroffenen Functional Clusters konsumieren die Design-Artefakte direkt, um Runtime-Header, Initialisierungsdaten oder Deskriptoren zu erzeugen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektureller Sonderfall:</strong> Laut AUTOSAR-Spezifikation handelt es sich um einen seltenen Ausnahmefall (<em>rare case</em>). Die Adaptive Platform erfordert für die meisten Functional Clusters (z. B. <code>ara::exec</code>, <code>ara::com</code>, <code>ara::phm</code>) plattform-, prozess- und hardwareabhängige Bindungen, die normativ in separaten Manifesten (<code>MachineManifest</code>, <code>ExecutionManifest</code>, <code>ServiceInstanceDeployment</code>) gepflegt werden müssen.</li>\n<li><strong>Konfigurationsaufwand:</strong> Entwickler und Integratoren sind bei Funktionsclustern, die dieser Strategie folgen, von der Pflege und Synchronisation separater Konfigurationsmodelle befreit; Design-Inkonsistenzen zwischen Entwurf und Deployment werden konstruktiv ausgeschlossen.</li>\n<li><strong>Einschränkung:</strong> Die Strategie ist nur anwendbar, wenn das Design alle operativen Parameter für das Zielsystem vollständig determiniert und keine maschinenspezifischen Varianten (wie IP-Adressen, Hardware-Port-Ressourcen oder Startup-Konfigurationen) dynamisch zur Systemintegration hinzukommen.</li>\n</ul>"}, {"id": "FIG-0e19fe94f088e6f0", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Metamodell-Strategiediagramm (informelle „Cloud“-Darstellung auf Methodik-Ebene, kein formales UML-Klassen- oder Verhaltensdiagramm).</li>\n<li><strong>Technischer Zweck & Kontext:</strong> Einordnung innerhalb der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_TPS_MachineConfiguration</code>, Kapitel 2 <em>Modeling Strategies for deriving M1 Model Content</em>). Das Diagramm visualisiert die vierte Modellierungsstrategie (Abschnitt 2.4.1), bei der die Parametrierung eines Functional Clusters (FC) bzw. der Machine vollständig und ausschließlich aus dem M1-Entwurfsmodell (<em>Design Model</em>) bezogen wird, ohne dass ein separates Konfigurations- oder Deployment-Modell (<em>Configuration Model</em>) existiert oder instanziiert werden muss.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><code>Design</code>: Symbolisiert die Gesamtheit der M1-Design-Artefakte (z. B. SWC-Typdefinitionen, Service Interfaces, System-Architektur-Modelle).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Singuläre Entität ohne Relationen oder Kanten.</li>\n<li>Es existiert keine Ziel-Konfigurationsentität und somit kein M2-Mapping, keine Transformationsbeziehung und keine Referenzierungssemantik (wie <code>instanceRef</code> oder flache Referenzen).</li>\n<li>Formal-syntaktische Metamodell-Stereotypen («atpSplitable», «isOfType») sind im Schaubild nicht instanziiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Laufzeitverhalten:</strong> Nicht zutreffend; rein statisches, konzeptionelles Modellierungs-Paradigma.</li>\n<li><strong>Tooling- & Generierungs-Pipeline:</strong></li>\n<li>Zur Generierungszeit entfällt der Schritt der M1-Modelltransformation oder der Synthese eines separaten Manifest-Zwischenmodells.</li>\n<li>Generatoren des betroffenen Functional Clusters konsumieren die Design-Artefakte direkt, um Runtime-Header, Initialisierungsdaten oder Deskriptoren zu erzeugen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektureller Sonderfall:</strong> Laut AUTOSAR-Spezifikation handelt es sich um einen seltenen Ausnahmefall (<em>rare case</em>). Die Adaptive Platform erfordert für die meisten Functional Clusters (z. B. <code>ara::exec</code>, <code>ara::com</code>, <code>ara::phm</code>) plattform-, prozess- und hardwareabhängige Bindungen, die normativ in separaten Manifesten (<code>MachineManifest</code>, <code>ExecutionManifest</code>, <code>ServiceInstanceDeployment</code>) gepflegt werden müssen.</li>\n<li><strong>Konfigurationsaufwand:</strong> Entwickler und Integratoren sind bei Funktionsclustern, die dieser Strategie folgen, von der Pflege und Synchronisation separater Konfigurationsmodelle befreit; Design-Inkonsistenzen zwischen Entwurf und Deployment werden konstruktiv ausgeschlossen.</li>\n<li><strong>Einschränkung:</strong> Die Strategie ist nur anwendbar, wenn das Design alle operativen Parameter für das Zielsystem vollständig determiniert und keine maschinenspezifischen Varianten (wie IP-Adressen, Hardware-Port-Ressourcen oder Startup-Konfigurationen) dynamisch zur Systemintegration hinzukommen.</li>\n</ul>"}], "trans": [{"from": "FIG-0cfd9a04da3b8e74", "to": "FIG-0e19fe94f088e6f0", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
